import { findAndRemoveImports, getFileCategory, parseFrontmatter } from '@mintlify/common';
import { getMdx } from '@mintlify/common/server-mdx';
import { preparseMdxTree } from '@mintlify/prebuild';
import fse from 'fs-extra';
import { mkdtemp, readdir, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
const testPaths = vi.hoisted(() => ({ cmd: '', public: '', props: '' }));
vi.mock('../constants.js', () => ({
    get CMD_EXEC_PATH() {
        return testPaths.cmd;
    },
    get NEXT_PUBLIC_PATH() {
        return testPaths.public;
    },
    get NEXT_PROPS_PATH() {
        return testPaths.props;
    },
}));
vi.mock('../local-preview/listener/utils.js', () => ({
    getCurrentVariables: vi.fn(async () => ({})),
    getMintIgnoreGlobs: vi.fn(() => []),
    handleParseError: vi.fn(),
    normalizePathForComparison: (path) => (path.startsWith('/') ? path : `/${path}`).toLowerCase(),
    suppressParseError: vi.fn(),
}));
import { generateDependentSnippets } from '../local-preview/listener/generateDependentSnippets.js';
import { generatePagesWithImports } from '../local-preview/listener/generatePagesWithImports.js';
import { initializeImportCache, updateImportCacheForFile, } from '../local-preview/listener/importCache.js';
import { regenerateAllSnippets } from '../local-preview/listener/regenerateAllSnippets.js';
import { ensurePageCompiled, markOnDemandPagesReady } from '../local-preview/on-demand-page.js';
import { PACKAGE_BUILD_PROPS_FILE, PackagesDev } from '../local-preview/packages/dev.js';
import { getPackageImportOptions, setPackageImportOptions, } from '../local-preview/packages/state.js';
import { PackageIslandCollector } from '../packages/collect.js';
const PLAIN_TOGGLE = 'export const Toggle = () => <span>plain toggle</span>;\n';
const PACKAGE_TOGGLE = 'import { Switch } from "@acme/ui";\n\nexport const Toggle = () => <Switch />;\n';
const BROKEN_TOGGLE = 'import { Switch } from "@acme/ui";\n\nexport const Toggle = () => <Switch;\n';
const PLAIN_WRAPPER = 'export const Wrapper = () => <span>plain wrapper</span>;\n';
const TOGGLE_WRAPPER = 'import { Toggle } from "/snippets/toggle.jsx";\n\nexport const Wrapper = () => <Toggle />;\n';
const TOGGLE_OUTPUTS = [
    'snippets/wrapper.jsx',
    'snippets/intro.mdx',
    'toggle-page.mdx',
    'wrapper-page.mdx',
];
const WRAPPER_OUTPUTS = ['snippets/wrapper.jsx', 'wrapper-page.mdx'];
const TOGGLE_IMPORT = 'import {Toggle} from "/snippets/toggle.jsx";';
const WRAPPER_IMPORT = 'import {Wrapper} from "/snippets/wrapper.jsx";';
let heldBuild;
let releaseBuild = () => { };
const fakeBuild = async ({ islands, outDir, }) => {
    await heldBuild;
    await fse.ensureDir(outDir);
    const built = {};
    for (const { id } of islands) {
        await fse.outputFile(join(outDir, 'client/islands', `${id}.js`), 'export {}');
        built[id] = {
            entry: `client/islands/${id}.js`,
            prefix: `mi-${id}-`,
            html: `<svg data-id="${id}"></svg>`,
        };
    }
    return {
        ok: true,
        manifest: {
            version: 1,
            builderVersion: 'test',
            buildId: `b${islands.length}`,
            depsHash: 'd',
            islandsHash: 'i',
            react: { version: '18.3.1', domVersion: '18.3.1' },
            packages: {},
            css: [],
            clientAccess: {
                version: 1,
                files: Object.fromEntries(islands.map(({ id }) => [`client/islands/${id}.js`, [id]])),
                globalFiles: [],
            },
            islands: built,
            files: islands.map(({ id }) => ({
                path: `client/islands/${id}.js`,
                bytes: 9,
                gzipBytes: 9,
                integrity: 'sha384-fixture',
            })),
            diagnostics: [],
        },
        stats: {
            installMs: 0,
            bundleMs: 0,
            renderMs: 0,
            totalMs: 0,
            clientBytes: 0,
            clientGzipBytes: 0,
            serverBytes: 0,
            islandClientGzipBytes: {},
            reactDirs: { react: [], 'react-dom': [] },
        },
        localFiles: [],
        missingLocalFiles: [],
    };
};
describe('package snippet membership in the mint dev watcher', () => {
    let root;
    let dev;
    let builds;
    const buildWaiters = new Set();
    const untilBuilt = (count) => new Promise((resolve) => {
        const check = () => {
            if (builds < count)
                return;
            buildWaiters.delete(check);
            resolve();
        };
        buildWaiters.add(check);
        check();
    });
    const docs = (file) => join(testPaths.cmd, file);
    const output = (file) => fse.readFile(join(file.startsWith('snippets/') ? testPaths.public : testPaths.props, file), 'utf8');
    const outputs = (files) => Promise.all(files.map(output));
    const packageSnippets = async () => {
        const published = [...(getPackageImportOptions()?.packageSnippets ?? [])].sort();
        const props = await fse.readJson(join(testPaths.props, PACKAGE_BUILD_PROPS_FILE));
        expect(props.packageSnippets).toEqual(published);
        return published;
    };
    const expectKept = (content, importLine, inlined) => {
        expect(content).toContain(importLine);
        expect(content).not.toContain(inlined);
    };
    const expectInlined = (content, marker) => {
        expect(content).not.toContain('import');
        expect(content).toContain(marker);
    };
    const changeSnippet = async (file, content) => {
        await fse.outputFile(docs(file), content);
        await updateImportCacheForFile(testPaths.cmd, file);
        await dev.onFileChange(file, 'snippet-v2');
    };
    const regenerate = async (file) => {
        const content = await fse.readFile(docs(file), 'utf8');
        const tree = await preparseMdxTree(content, testPaths.cmd, docs(file), vi.fn());
        const updated = await generateDependentSnippets(file, await findAndRemoveImports(tree));
        await generatePagesWithImports(new Set(updated));
    };
    const saveSnippet = async (file, content) => {
        await changeSnippet(file, content);
        await regenerate(file);
    };
    const editSnippet = async (file, content) => {
        const settled = builds + 1;
        await saveSnippet(file, content);
        await untilBuilt(settled);
    };
    const legacySnippets = async () => {
        const dir = join(testPaths.public, '_snippets');
        const names = (await fse.pathExists(dir)) ? await readdir(dir) : [];
        return Promise.all(names.map(async (name) => ({
            snippetFileLocation: name,
            content: await fse.readFile(join(dir, name), 'utf8'),
        })));
    };
    const render = async (page) => {
        const { buildId, islands, packageNames, packageSnippets } = await fse.readJson(join(testPaths.props, PACKAGE_BUILD_PROPS_FILE));
        const compiled = await getMdx({
            path: page.replace(/\.mdx$/, ''),
            content: parseFrontmatter(await output(page)).body,
            metadata: {},
            snippets: await legacySnippets(),
            subdomain: 'local',
            codeStyling: undefined,
            tailwindSelectors: [],
            packageBuild: { buildId, islands, packageNames, packageSnippets },
        });
        expect(compiled.parseFailed).toBeUndefined();
        return compiled.mdxExtracts.islands ?? {};
    };
    const holdBuilds = () => {
        heldBuild = new Promise((resolve) => {
            releaseBuild = () => {
                heldBuild = undefined;
                resolve();
            };
        });
    };
    const start = async ({ toggle, wrapper }) => {
        await fse.outputFile(docs('snippets/toggle.jsx'), toggle);
        await fse.outputFile(docs('snippets/wrapper.jsx'), wrapper);
        await dev.init();
        await initializeImportCache(testPaths.cmd);
        const snippets = await regenerateAllSnippets();
        await generatePagesWithImports(new Set(snippets));
        builds = 0;
    };
    beforeAll(async () => {
        // getMdx loads its syntax highlighter on first use. Pay that once here instead of in
        // whichever test renders first.
        await getMdx({
            path: 'warm-up',
            content: '',
            metadata: {},
            snippets: [],
            subdomain: 'local',
            codeStyling: undefined,
            tailwindSelectors: [],
        });
    });
    beforeEach(async () => {
        root = await mkdtemp(join(tmpdir(), 'packages-dev-snippets-'));
        testPaths.cmd = join(root, 'docs');
        testPaths.public = join(root, 'public');
        testPaths.props = join(root, 'props');
        builds = 0;
        await fse.outputJson(docs('docs.json'), { name: 'Docs', packages: {} });
        await fse.outputJson(docs('package.json'), { dependencies: { '@acme/ui': '1.0.0' } });
        await fse.outputFile(docs('snippets/intro.mdx'), 'import { Toggle } from "/snippets/toggle.jsx";\n\nIntro text\n\n<Toggle />\n');
        await fse.outputFile(docs('toggle-page.mdx'), 'import { Toggle } from "/snippets/toggle.jsx";\n\n<Toggle />\n');
        await fse.outputFile(docs('wrapper-page.mdx'), 'import { Wrapper } from "/snippets/wrapper.jsx";\n\n<Wrapper />\n');
        vi.spyOn(console, 'log').mockImplementation(() => { });
        dev = new PackagesDev({
            docsRoot: testPaths.cmd,
            buildsDir: join(root, 'builds'),
            propsPath: testPaths.props,
            onRebuilt: () => {
                builds++;
                for (const check of buildWaiters)
                    check();
            },
            regenerateSnippets: regenerateAllSnippets,
            reporter: {
                building: () => { },
                built: () => { },
                failed: () => { },
                missingNodeModules: () => { },
                islandErrors: () => { },
                configError: () => { },
            },
            debounceMs: 0,
            build: fakeBuild,
        });
    });
    afterEach(async () => {
        buildWaiters.clear();
        releaseBuild();
        await dev.close();
        setPackageImportOptions(undefined);
        vi.mocked(console.log).mockRestore();
        await rm(root, { recursive: true, force: true });
    });
    it('turns a snippet into an island when it starts importing a package and back when it stops', async () => {
        await start({ toggle: PLAIN_TOGGLE, wrapper: TOGGLE_WRAPPER });
        const initial = await outputs(TOGGLE_OUTPUTS);
        expect(await packageSnippets()).toEqual([]);
        expectInlined(await output('snippets/wrapper.jsx'), 'plain toggle');
        expectInlined(await output('toggle-page.mdx'), 'plain toggle');
        await editSnippet('snippets/toggle.jsx', PACKAGE_TOGGLE);
        expect(await packageSnippets()).toEqual(['/snippets/toggle.jsx', '/snippets/wrapper.jsx']);
        expectKept(await output('snippets/wrapper.jsx'), TOGGLE_IMPORT, 'export const Toggle');
        expectKept(await output('snippets/intro.mdx'), TOGGLE_IMPORT, 'export const Toggle');
        expectKept(await output('toggle-page.mdx'), TOGGLE_IMPORT, 'export const Toggle');
        expectKept(await output('wrapper-page.mdx'), WRAPPER_IMPORT, 'export const Wrapper');
        expect(builds).toBe(1);
        await editSnippet('snippets/toggle.jsx', PLAIN_TOGGLE);
        expect(await packageSnippets()).toEqual([]);
        expect(await outputs(TOGGLE_OUTPUTS)).toEqual(initial);
        expect(builds).toBe(2);
    });
    it('makes a wrapper an island when it starts importing a package snippet and back when it stops', async () => {
        await start({ toggle: PACKAGE_TOGGLE, wrapper: PLAIN_WRAPPER });
        const initial = await outputs(WRAPPER_OUTPUTS);
        expect(await packageSnippets()).toEqual(['/snippets/toggle.jsx']);
        expectInlined(await output('wrapper-page.mdx'), 'plain wrapper');
        await editSnippet('snippets/wrapper.jsx', TOGGLE_WRAPPER);
        expect(await packageSnippets()).toEqual(['/snippets/toggle.jsx', '/snippets/wrapper.jsx']);
        expectKept(await output('snippets/wrapper.jsx'), TOGGLE_IMPORT, 'export const Toggle');
        expectKept(await output('wrapper-page.mdx'), WRAPPER_IMPORT, 'export const Wrapper');
        await editSnippet('snippets/wrapper.jsx', PLAIN_WRAPPER);
        expect(await packageSnippets()).toEqual(['/snippets/toggle.jsx']);
        expect(await outputs(WRAPPER_OUTPUTS)).toEqual(initial);
        expect(builds).toBe(2);
    });
    it('keeps a package snippet and its importers on islands while it fails to parse, until it is deleted', async () => {
        const islands = ['/snippets/toggle.jsx', '/snippets/wrapper.jsx'];
        await start({ toggle: PACKAGE_TOGGLE, wrapper: TOGGLE_WRAPPER });
        const initial = await outputs(TOGGLE_OUTPUTS);
        expect(await packageSnippets()).toEqual(islands);
        await editSnippet('snippets/toggle.jsx', BROKEN_TOGGLE);
        expect(await packageSnippets()).toEqual(islands);
        const parseError = 'A parsing error occurred';
        expectKept(await output('snippets/wrapper.jsx'), TOGGLE_IMPORT, parseError);
        expectKept(await output('snippets/intro.mdx'), TOGGLE_IMPORT, parseError);
        expectKept(await output('toggle-page.mdx'), TOGGLE_IMPORT, parseError);
        expectKept(await output('wrapper-page.mdx'), WRAPPER_IMPORT, parseError);
        await editSnippet('snippets/toggle.jsx', PACKAGE_TOGGLE);
        expect(await packageSnippets()).toEqual(islands);
        expect(await outputs(TOGGLE_OUTPUTS)).toEqual(initial);
        const settled = builds + 1;
        await fse.remove(docs('snippets/toggle.jsx'));
        await dev.onFileChange('snippets/toggle.jsx', 'snippet-v2');
        await untilBuilt(settled);
        expect(await packageSnippets()).toEqual([]);
    });
    it('keeps a package snippet that fails to parse on islands when package.json and docs.json are saved', async () => {
        const islands = ['/snippets/toggle.jsx', '/snippets/wrapper.jsx'];
        await start({ toggle: PACKAGE_TOGGLE, wrapper: TOGGLE_WRAPPER });
        const initial = await outputs(TOGGLE_OUTPUTS);
        await editSnippet('snippets/toggle.jsx', BROKEN_TOGGLE);
        const broken = await outputs(TOGGLE_OUTPUTS);
        const manifestBuilt = builds + 1;
        await fse.outputJson(docs('package.json'), { dependencies: { '@acme/ui': '1.0.0' } });
        await dev.onFileChange('package.json', getFileCategory('package.json'));
        await fse.outputJson(docs('docs.json'), { name: 'Docs', packages: {} });
        await dev.onFileChange('docs.json', 'docsConfig');
        await untilBuilt(manifestBuilt);
        expect(await packageSnippets()).toEqual(islands);
        expect(await outputs(TOGGLE_OUTPUTS)).toEqual(broken);
        expectKept(await output('snippets/wrapper.jsx'), TOGGLE_IMPORT, 'A parsing error occurred');
        expectKept(await output('toggle-page.mdx'), TOGGLE_IMPORT, 'A parsing error occurred');
        await editSnippet('snippets/toggle.jsx', PACKAGE_TOGGLE);
        expect(await packageSnippets()).toEqual(islands);
        expect(await outputs(TOGGLE_OUTPUTS)).toEqual(initial);
    });
    it('drops a package snippet that failed to parse once it is deleted before docs.json is saved', async () => {
        await start({ toggle: PACKAGE_TOGGLE, wrapper: TOGGLE_WRAPPER });
        await editSnippet('snippets/toggle.jsx', BROKEN_TOGGLE);
        await fse.outputJson(docs('docs.json'), { name: 'Docs', packages: {} });
        await dev.onFileChange('docs.json', 'docsConfig');
        expect(await packageSnippets()).toEqual(['/snippets/toggle.jsx', '/snippets/wrapper.jsx']);
        await fse.remove(docs('snippets/toggle.jsx'));
        await fse.outputJson(docs('docs.json'), { name: 'Docs', packages: {} });
        await dev.onFileChange('docs.json', 'docsConfig');
        expect(await packageSnippets()).toEqual([]);
    });
    it('keeps a package snippet that broke while docs.json was invalid once docs.json is fixed', async () => {
        const islands = ['/snippets/toggle.jsx', '/snippets/wrapper.jsx'];
        await start({ toggle: PACKAGE_TOGGLE, wrapper: TOGGLE_WRAPPER });
        await fse.outputFile(docs('docs.json'), '{ "name": ');
        await dev.onFileChange('docs.json', 'docsConfig');
        await editSnippet('snippets/toggle.jsx', BROKEN_TOGGLE);
        expect(await packageSnippets()).toEqual(islands);
        const broken = await outputs(TOGGLE_OUTPUTS);
        await fse.outputJson(docs('docs.json'), { name: 'Docs', packages: {} });
        await dev.onFileChange('docs.json', 'docsConfig');
        expect(await packageSnippets()).toEqual(islands);
        expect(await outputs(TOGGLE_OUTPUTS)).toEqual(broken);
    });
    it('regenerates snippet copies when packages are enabled, gain a dependency, or are disabled', async () => {
        const BADGE_IMPORT = 'import {Badge} from "@acme/ui";';
        await fse.outputJson(docs('docs.json'), { name: 'Docs' });
        await fse.outputJson(docs('package.json'), { dependencies: {} });
        await fse.outputFile(docs('snippets/badge.mdx'), `${BADGE_IMPORT}\n\n<Badge />\n`);
        await start({ toggle: PACKAGE_TOGGLE, wrapper: PLAIN_WRAPPER });
        const initial = await outputs(['snippets/intro.mdx', 'snippets/badge.mdx']);
        expect(getPackageImportOptions()).toBeUndefined();
        expectInlined(await output('snippets/intro.mdx'), 'export const Toggle');
        expect(await output('snippets/badge.mdx')).not.toContain(BADGE_IMPORT);
        await fse.outputJson(docs('docs.json'), { name: 'Docs', packages: {} });
        await dev.onFileChange('docs.json', 'docsConfig');
        expect(await packageSnippets()).toEqual(['/snippets/toggle.jsx']);
        expectKept(await output('snippets/intro.mdx'), TOGGLE_IMPORT, 'export const Toggle');
        await fse.outputJson(docs('package.json'), { dependencies: { '@acme/ui': '1.0.0' } });
        await dev.onFileChange('package.json', getFileCategory('package.json'));
        expect(await output('snippets/badge.mdx')).toContain(BADGE_IMPORT);
        await fse.outputJson(docs('docs.json'), { name: 'Docs' });
        await dev.onFileChange('docs.json', 'docsConfig');
        expect(getPackageImportOptions()).toBeUndefined();
        expect(await outputs(['snippets/intro.mdx', 'snippets/badge.mdx'])).toEqual(initial);
    });
    it('renders placeholders for the islands a snippet edit adds until the rebuild finishes', async () => {
        await start({ toggle: PLAIN_TOGGLE, wrapper: TOGGLE_WRAPPER });
        expect(await render('toggle-page.mdx')).toEqual({});
        holdBuilds();
        const settled = builds + 1;
        await saveSnippet('snippets/toggle.jsx', PACKAGE_TOGGLE);
        const pending = { ...(await render('toggle-page.mdx')), ...(await render('wrapper-page.mdx')) };
        expect(Object.keys(pending)).toHaveLength(2);
        for (const [id, island] of Object.entries(pending)) {
            expect(island).toEqual({ prefix: `mi-${id}-` });
        }
        releaseBuild();
        await untilBuilt(settled);
        const built = { ...(await render('toggle-page.mdx')), ...(await render('wrapper-page.mdx')) };
        expect(Object.keys(built)).toEqual(Object.keys(pending));
        for (const [id, island] of Object.entries(built)) {
            expect(island.html).toBe(`<svg data-id="${id}"></svg>`);
        }
    });
    it('keeps rendering the islands a snippet edit removes until the watcher recompiles the pages', async () => {
        await fse.outputFile(docs('snippets/switches.mdx'), 'import { Switch } from "@acme/ui";\n\n<Switch />\n');
        await fse.outputFile(docs('switch-page.mdx'), 'import Switches from "/snippets/switches.mdx";\n\n<Switches />\n');
        await start({ toggle: PLAIN_TOGGLE, wrapper: PLAIN_WRAPPER });
        const switches = await render('switch-page.mdx');
        expect(Object.keys(switches)).toHaveLength(1);
        holdBuilds();
        await changeSnippet('snippets/switches.mdx', 'No switch\n');
        expect(await render('switch-page.mdx')).toEqual(switches);
        await regenerate('snippets/switches.mdx');
        expect(await render('switch-page.mdx')).toEqual({});
    });
    it('recompiles pages on request after a package snippet change, and keeps serving ones that failed to compile', async () => {
        markOnDemandPagesReady();
        await fse.outputFile(docs('broken.mdx'), '# Broken\n\n<div>\n\nunclosed {\n');
        await fse.outputFile(docs('plain.mdx'), '# Plain\n');
        await start({ toggle: PLAIN_TOGGLE, wrapper: TOGGLE_WRAPPER });
        await ensurePageCompiled('/broken', { silent: true });
        await ensurePageCompiled('/plain', { silent: true });
        const broken = await output('broken.mdx');
        const compiledAt = (await fse.stat(join(testPaths.props, 'plain.mdx'))).mtimeMs;
        await saveSnippet('snippets/toggle.jsx', PACKAGE_TOGGLE);
        await ensurePageCompiled('/broken', { silent: true });
        await ensurePageCompiled('/plain', { silent: true });
        expect(await output('broken.mdx')).toBe(broken);
        expect((await fse.stat(join(testPaths.props, 'plain.mdx'))).mtimeMs).toBeGreaterThanOrEqual(compiledAt);
    });
    it('drops a snippet update that finishes after packages are disabled', async () => {
        await start({ toggle: PLAIN_TOGGLE, wrapper: TOGGLE_WRAPPER });
        const collectAll = PackageIslandCollector.prototype.collectAll;
        let release = () => { };
        const held = new Promise((resolve) => {
            release = resolve;
        });
        const spy = vi
            .spyOn(PackageIslandCollector.prototype, 'collectAll')
            .mockImplementation(async function () {
            await held;
            return collectAll.call(this);
        });
        try {
            await fse.outputFile(docs('snippets/toggle.jsx'), PACKAGE_TOGGLE);
            const change = dev.onFileChange('snippets/toggle.jsx', 'snippet-v2');
            await fse.outputJson(docs('docs.json'), { name: 'Docs' });
            await dev.onFileChange('docs.json', 'docsConfig');
            release();
            await change;
        }
        finally {
            spy.mockRestore();
        }
        expect(dev.enabled).toBe(false);
        expect(getPackageImportOptions()).toBeUndefined();
        expect(await fse.pathExists(join(testPaths.props, PACKAGE_BUILD_PROPS_FILE))).toBe(false);
    });
});
